//! Ops P32: execution-run checkpoint, retry, compensation, and budget integrity.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;pub const CONTENT_TYPE:&str="application/vnd.aurora.ops.run-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ExecutionEvent4{pub event_id:String,pub sequence:u64,pub kind:String,pub status:String,pub effect:String,pub checkpoint:u64,pub retry_of:Option<String>,pub artifact_digest:String,pub replay_identity:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct RunIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub events:Vec<ExecutionEvent4>,pub required_event_order:Vec<String>,pub required_effect_order:Vec<String>,pub checkpoint:u64,pub max_sequence:u64,pub action_budget:usize,pub action_count:usize,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:String,pub adversarial_events:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct RunIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct RunIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub event_order:Vec<String>,pub committed_order:Vec<String>,pub retry_order:Vec<String>,pub compensation_order:Vec<String>,pub duplicate_order:Vec<String>,pub unresolved_order:Vec<String>,pub omitted_order:Vec<String>,pub effect_order:Vec<String>,pub checkpoint_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:RunIntegrityArtifact4}
#[derive(Debug,Error)] pub enum RunIntegrityError{#[error("run integrity input is invalid: {0}")] Invalid(String),#[error("run integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->RunIntegrityError{RunIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"ops","consumers":["execution controller","workflow fabric","provenance ledger","operator workbench"],"behavior":format!("qualify checkpointed execution runs at {scale} ({mode})"),"value":"prevents duplicate, over-budget, unreplayable, or unauthorized effects from being represented as complete","input_schema":"RunIntegrityRequest4@1","output_schema":"RunIntegrityCard7@1","effects":["emit:run-card","retain:retry-compensation","block:unsafe-run"],"permissions":["read:local-run-log"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&RunIntegrityCard7)->Result<(),RunIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("run identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.event_order,&c.committed_order,&c.retry_order,&c.compensation_order,&c.duplicate_order,&c.unresolved_order,&c.omitted_order,&c.effect_order,&c.checkpoint_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("run vectors are not canonical"));}}let ids=c.event_order.iter().collect::<BTreeSet<_>>();let states=c.committed_order.iter().chain(&c.unresolved_order).chain(&c.omitted_order).chain(&c.duplicate_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("event states do not partition events"));}Ok(())}
pub fn qualify(q:&RunIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<RunIntegrityCard7,RunIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.events.is_empty()||q.required_event_order.is_empty()||!canonical(&q.required_event_order)||!canonical(&q.required_effect_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.action_budget==0{return Err(invalid("run identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.events.clone();rows.sort_by(|a,b|a.event_id.cmp(&b.event_id));let mut seen=BTreeSet::new();let mut seqs=BTreeSet::new();let mut committed=BTreeSet::new();let mut retry=BTreeSet::new();let mut compensation=BTreeSet::new();let mut duplicate=BTreeSet::new();let mut unresolved=BTreeSet::new();let mut omitted=BTreeSet::new();let mut effects=BTreeSet::new();let mut checkpoints=BTreeSet::new();let mut evidence=BTreeSet::new();for e in &rows{if e.event_id.trim().is_empty()||!seen.insert(e.event_id.clone())||!seqs.insert(e.sequence)||e.kind.trim().is_empty()||e.status.trim().is_empty()||e.effect.trim().is_empty()||!digest(&e.artifact_digest)||!digest(&e.replay_identity)||!e.local||!e.aggregate_only{return Err(invalid("event identity, sequence, digest, effect, or locality is invalid"));}effects.insert(format!("{}:{}",e.event_id,e.effect));checkpoints.insert(format!("{}:{}",e.event_id,e.checkpoint));e.retry_of.as_ref().map(|x|{retry.insert(format!("{}:retry-of:{x}",e.event_id));});if e.kind=="compensation"{compensation.insert(e.event_id.clone());}evidence.insert(e.artifact_digest.clone());if e.replay_identity!=q.replay_identity||e.status=="unknown"{unresolved.insert(e.event_id.clone());}else if e.sequence>q.max_sequence||e.checkpoint>q.checkpoint||e.status!="committed"{duplicate.insert(e.event_id.clone());}else if !q.required_event_order.contains(&e.event_id){omitted.insert(e.event_id.clone());}else{committed.insert(e.event_id.clone());}}let missing=q.required_event_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_approval||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||q.action_count>q.action_budget||rows.len()>q.action_budget;if global{omitted.extend(seen.iter().cloned());committed.clear();duplicate.clear();unresolved.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unresolved.is_empty(){"unknown"}else if !duplicate.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let event_order=seen.iter().cloned().collect::<Vec<_>>();let committed_order=committed.into_iter().collect::<Vec<_>>();let retry_order=retry.into_iter().collect::<Vec<_>>();let compensation_order=compensation.into_iter().collect::<Vec<_>>();let duplicate_order=duplicate.into_iter().collect::<Vec<_>>();let unresolved_order=unresolved.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"event_order":event_order,"committed_order":committed_order,"retry_order":retry_order,"compensation_order":compensation_order,"duplicate_order":duplicate_order,"unresolved_order":unresolved_order,"omitted_order":omitted_order,"effect_order":effects.into_iter().collect::<Vec<_>>(),"checkpoint_order":checkpoints.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|RunIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:run:{}",q.request_id)]}else{vec!["block:unsafe-run".into()]};let artifact=RunIntegrityArtifact4{artifact_id:format!("ops-run:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=RunIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),event_order:body["event_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),committed_order,retry_order,compensation_order,duplicate_order,unresolved_order,omitted_order,effect_order:body["effect_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),checkpoint_order:body["checkpoint_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
